public static void setImageDrawable(EfficientCacheView cacheView, int viewId,
            Drawable drawable) {
        View view = cacheView.findViewByIdEfficient(viewId);
        if (view instanceof ImageView) {
            ((ImageView) view).setImageDrawable(drawable);
        }
    }
